-- group by
select * from sales;
select * from products;
select * from geo;
select * from people;

-- total revenue generated by each category
-- which category has highest revenue
select pr.category, sum(s.amount) as revenue
from sales s
left join products pr
ON s.PID=pr.PID
GROUP by pr.category
order by revenue desc;

-- monthly wise sales
select sum(amount) as total_sales, monthname(saledate) as month
from sales
GROUP by month
order by total_sales desc; -- jan

select sum(amount) as total_sales, monthname(saledate) as month
from sales
where year(saledate) = '2022'
GROUP by month
order by total_sales desc; -- jan

select sum(amount) as total_sales, monthname(saledate) as month
from sales
where year(saledate) = '2021'
GROUP by month
order by total_sales desc; -- march

-- highest sale made person
select sum(s.amount) as total_sales, p.salesperson
from sales s
left join people p
on s.SPID = p.SPID
GROUP by salesperson
order by total_sales desc;  -- Wilone O'Kielt

-- highest boxes sold  product
select sum(s.boxes) as totalno_boxes,pr.product, pr.pid
from sales s
left join products pr
on s.PID = pr.PID
GROUP by pid
order by totalno_boxes desc;  -- Orange Choco

-- lowest no. of customers in which geo
select g.geo, sum(s.customers) as total_cust
from sales s
left join geo g
on g.GeoID = s.GeoID
group by g.geo
order by total_cust; -- usa

-- count members in each team
select count(s.spid) as No_of_members, p.team
from sales s
left join people p
on s.SPID = p.SPID
group by team
order by No_of_members desc;

-- Find Top Performing Salesperson
select sum(s.amount) as Total_sales, p.Salesperson
from sales s
left join people p
on s.SPID = p.SPID
group by p.Salesperson
order by Total_sales desc;

-- Total Boxes Sold in Each Country
select g.geo as country, sum(s.boxes) as total_no_of_boxes
from sales s
left join geo g
on g.GeoID = s.GeoID
group by country
order by total_no_of_boxes;

-- Count Products in Each Category
select category, count(product) as product_count
from products
GROUP by category
order by product_count desc;

-- LIMIT

SELECT *
FROM sales
LIMIT 10;

-- Identify top performing 10 person
select sum(s.amount) as Total_sales, p.Salesperson
from sales s
left join people p
on s.SPID = p.SPID
group by p.Salesperson
order by Total_sales desc
LIMIT 10;

-- find out which product has low average sales
select avg(s.amount) as Avg_sales, pr.product, pr.PID
from sales s
left join products pr
on s.PID = pr.PID
GROUP by pid
order by Avg_sales
LIMIT 1;  -- White Choc

-- average number of boxes for each products
select AVG(s.boxes) as avg_no_boxes, pr.product
from sales s
left join products pr
on s.PID = pr.PID
GROUP by product
order by avg_no_boxes desc;

-- which team made total sales above 100000
select sum(s.amount) as total_sales, p.team
from sales s
left join people p
on s.SPID = p.SPID
group by team
HAVING total_sales > 100000 
order by total_sales desc;

-- count number of sales per spid findout person made numbers of sales above 300
select count(s.amount) as no_of_sales, p.Salesperson,p.SPID
from sales s
left join people p
on s.SPID = p.SPID
group by spid
HAVING no_of_sales > 300
order by spid desc;

-- for year 2022 and identify their names - 50 
select count(s.amount) as no_of_sales,year(s.SaleDate) as year, p.Salesperson,p.SPID
from sales s
left join people p
on s.SPID = p.SPID
where year(s.SaleDate) = '2022'
group by spid, year
HAVING no_of_sales > 50
order by no_of_sales desc;













